begin;
create extension if not exists pgtap with schema extensions;
select plan(20);
select ok(not has_function_privilege('authenticated','academy.claim_worker_acceptance_job()','execute'),'No browser claim permission');
select ok(not has_function_privilege('anon','academy.claim_worker_acceptance_job()','execute'),'No anonymous claim permission');
select ok(has_function_privilege('service_role','academy.claim_worker_acceptance_job()','execute'),'Worker can claim');
-- Rolled back; never run this test against production.
select academy.enqueue_job('normalize_source','test:unrelated-worker','{"identifier":"2401.12345"}');
update academy.production_jobs set attempts=max_attempts where idempotency_key='test:unrelated-worker';
create temporary table before_queue as select * from academy.production_jobs;
select is((select count(*) from academy.claim_worker_acceptance_job()),0::bigint,'No fallback to unrelated queue');
select is((select count(*) from (select * from before_queue except select * from academy.production_jobs) d),0::bigint,'Unrelated exhausted rows unchanged');
create temporary table acceptance_id as select academy.enqueue_job('normalize_source','prod002:worker:normalize:v1','{"identifier":"doi:10.9999/academy-prod002-worker-acceptance","synthetic":true,"doNotPublish":true}') id;
update academy.production_jobs set payload='{"identifier":"2401.12345"}' where id=(select id from acceptance_id);
select is((select count(*) from academy.claim_worker_acceptance_job()),0::bigint,'Wrong fixture payload rejected');
update academy.production_jobs set payload='{"identifier":"doi:10.9999/academy-prod002-worker-acceptance","synthetic":true,"doNotPublish":true}',stage='metadata_enrichment' where id=(select id from acceptance_id);
select is((select count(*) from academy.claim_worker_acceptance_job()),0::bigint,'Metadata stage rejected even with matching key');
update academy.production_jobs set stage='normalize_source' where id=(select id from acceptance_id);
create temporary table acceptance_lease as select * from academy.claim_worker_acceptance_job();
select is((select id from acceptance_lease),(select id from acceptance_id),'Exact fixture claimed');
select is((select attempts from acceptance_lease),1,'One attempt');
select is((select count(*) from academy.claim_worker_acceptance_job()),0::bigint,'Live lease prevents duplicate claim');
select ok(academy.renew_job((select id from acceptance_lease),(select lease_token from acceptance_lease)),'Lease renews');
select ok(not academy.finish_job((select id from acceptance_lease),gen_random_uuid(),'{}'),'Wrong lease denied');
select ok(academy.finish_job((select id from acceptance_lease),(select lease_token from acceptance_lease),'{"canonicalId":"doi:10.9999/academy-prod002-worker-acceptance"}'),'Result persisted');
select is((select count(*) from academy.claim_worker_acceptance_job()),0::bigint,'Success never reclaimed');
select is(academy.enqueue_job('normalize_source','prod002:worker:normalize:v1','{}'),(select id from acceptance_id),'Repeat enqueue retains identity');
-- Exercise error/backoff/reclaim only on the transaction's synthetic fixture.
update academy.production_jobs set status='queued',attempts=0 where id=(select id from acceptance_id);
create temporary table failed_lease as select * from academy.claim_worker_acceptance_job();
select ok(academy.fail_job((select id from failed_lease),(select lease_token from failed_lease),'ACCEPTANCE_TEST'),'Failure persisted via existing RPC');
select is((select count(*) from academy.claim_worker_acceptance_job()),0::bigint,'Backoff prevents immediate retry');
update academy.production_jobs set available_at=now() where id=(select id from acceptance_id);
create temporary table retry_lease as select * from academy.claim_worker_acceptance_job();
select is((select attempts from retry_lease),2,'Retry increments attempt');
select ok(not academy.finish_job((select id from failed_lease),(select lease_token from failed_lease),'{}'),'Previous lease cannot finish retry');
select is((select count(*) from (select * from before_queue except select * from academy.production_jobs) d),0::bigint,'All unrelated rows preserved throughout');
select * from finish();
rollback;
